from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    def tsp(current_city: int, visited_cities: set, cost_so_far: int, cities_left: int) -> int:
        if cities_left == 1:
            return cost_so_far + distances[current_city][0]

        min_cost = float('inf')
        for next_city in range(1, len(distances)):
            if next_city not in visited_cities:
                new_visited_cities = visited_cities | {next_city}
                new_cost_so_far = cost_so_far + distances[current_city][next_city]
                new_cities_left = cities_left - 1
                min_cost = min(min_cost, tsp(next_city, new_visited_cities, new_cost_so_far, new_cities_left))

        return min_cost

    n = len(distances)
    start_city = 0
    visited_cities = {start_city}
    cities_left = n - 1
    total_cost = tsp(start_city, visited_cities, 0, cities_left)

