def min_travel_time(distance_ab: int, distance_to_road: int, desert_speed: int, road_speed: int) -> float:
    def time_to_b(x: int) -> float:
        if x == 0 or x == distance_ab:
            return (distance_ab - 2 * distance_to_road) / desert_speed
        else:
            y = ((distance_ab ** 2 - (x - distance_to_road) ** 2) ** 0.5)
            return (distance_to_road + y) / road_speed + (x - distance_to_road) / desert_speed

    min_time = float('inf')
    for x in range(0, distance_ab + 1):
        time = time_to_b(x)
        if time < min_time:
            min_time = time
    return min_time * 60

