    from itertools import combinations, permutations

    def valid_combination(comb):
        row_sums = [sum(comb[:3]), sum(comb[3:5]), comb[5]]
        return len(set(row_sums)) == 1

    total_numbers = len(numbers)
    if total_numbers < 6 or (total_numbers - 6) % 2 != 0:
