            valid_combinations.append(comb)

    count = 0
    for perm in permutations(valid_combinations[0]):
        if all(p in c for p, c in zip(perm, valid_combinations)):
            count += 1

    return count // (3 * 2 * 1)  # Account for overcounting due to permutations

