                      brocade_retail_price_per_meter: int, mulberry_retail_price_per_meter: int) -> float:

    def profit(x: int, y: int) -> float:
        material_cost = (x * brocade_cost_per_meter + y * mulberry_cost_per_meter)
        labor_cost = (x * brocade_days_per_meter * labor_cost_per_day + y * mulberry_days_per_meter * labor_cost_per_day)
        if material_cost + labor_cost > budget or x + y > max_production:
            return -float('inf')
        else:
            revenue = (x * brocade_retail_price_per_meter + y * mulberry_retail_price_per_meter)
            cost = material_cost + labor_cost
            return revenue - cost

    from scipy.optimize import minimize

    def objective_function(xy: Tuple[int, int]) -> float:
