        return -profit(x, y)

    initial_guess = [50, 50]
    bounds = [(0, max_production), (0, max_production)]

    result = minimize(objective_function, initial_guess, method='SLSQP', bounds=bounds)

    x, y = result.x
    return -profit(x, y)

