def solve_min_cost_days(shipping_cost: int, storage_cost_per_quintal_per_day: int, daily_distribution: int, max_storage_days: int) -> int:
    def total_cost(days: int) -> float:
        nonlocal shipping_cost, storage_cost_per_quintal_per_day, daily_distribution, max_storage_days
        if days > max_storage_days + 1:
            return float('inf')
        total_fruit = days * daily_distribution
        storage_days = max_storage_days - days + 1
        total_storage_cost = storage_days * storage_cost_per_quintal_per_day * total_fruit
        return (shipping_cost + total_storage_cost) / total_fruit

    min_cost, optimal_days = float('inf'), 0
    for days in range(1, max_storage_days + 2):
        cost = total_cost(days)
        if cost < min_cost:
            min_cost, optimal_days = cost, days

    return optimal_days

