def maximize_profit_price(price: int, customers: int, decrease_per_10k: int, new_customers_per_10k: int, cost_coeffs: List[float]) -> float:
    def profit(price: int, customers: int) -> float:
        revenue = price * customers
        operating_cost = (cost_coeffs[0] * customers + 
                          cost_coeffs[1] * customers**2 / 1000 +
                          cost_coeffs[2])
        return revenue - operating_cost * 1000

    def new_customers(price: int) -> int:
        return customers + ((price - price // 10000 * 10000) // decrease_per_10k * new_customers_per_10k)

    left, right = price - 50000, price
    while right - left > 1:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3
        profit_mid1 = profit(mid1, new_customers(mid1))
        profit_mid2 = profit(mid2, new_customers(mid2))

        if profit_mid1 > profit_mid2:
            right = mid2
        else:
            left = mid1

    return max(profit(left, new_customers(left)), profit(right, new_customers(right)))

