def binomial_coefficient(n: int, k: int) -> int:
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1

    C = [0] * (k + 1)
    C[0] = 1

    for i in range(1, n + 1):
        j = min(i, k)
        while j > 0:
            C[j] += C[j - 1]
            j -= 1

    return C[k]

def calculate_probability_score(total_questions: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    if total_questions * correct_points < target_score or (total_questions - target_score) % (correct_points + incorrect_points) != 0:
        return 0.0

    correct_answers = (target_score - total_questions * incorrect_points) // correct_points
    if correct_answers > total_questions:
        return 0.0

    probability = binomial_coefficient(total_questions, correct_answers)
    for i in range(correct_answers):
        probability *= (1 / 4)

    for i in range(total_questions - correct_answers):
        probability *= (3 / 4)

    return round(probability * 100, 2)

