def solve_gps_problem(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
    def parametric_point_on_line_segment(t: float, point1: Tuple[float, float, float], point2: Tuple[float, float, float]) -> Tuple[float, float, float]:
        return (point1[0] + t * (point2[0] - point1[0]),
                point1[1] + t * (point2[1] - point1[1]),
                point1[2] + t * (point2[2] - point1[2]))

    def distance_from_point_to_line(point: Tuple[float, float, float], line_start: Tuple[float, float, float], line_end: Tuple[float, float, float]) -> float:
        v1 = (line_end[0] - line_start[0], line_end[1] - line_start[1], line_end[2] - line_start[2])
        v2 = (point[0] - line_start[0], point[1] - line_start[1], point[2] - line_start[2])
        dot_product = sum(x * y for x, y in zip(v1, v2))
        magnitude_v1 = distance(line_start, line_end)
        if magnitude_v1 == 0:
            return distance_from_point_to_line(point, (line_start[0], line_start[1], line_start[2] + 0.01), line_end)  # Avoid division by zero
        t = dot_product / magnitude_v1
        projection = (line_start[0] + t * v1[0], line_start[1] + t * v1[1], line_start[2] + t * v1[2])
        return distance(point, projection)

    max_sum_distance = 0.0
    best_point = None

    for t in range(100):
        M = parametric_point_on_line_segment(t / 99, A, B)
        sum_distance = (distance_from_point_to_line(A, D, M) +
                        distance_from_point_to_line(B, D, M) +
                        distance_from_point_to_line(C, D, M))

        if sum_distance > max_sum_distance:
            max_sum_distance = sum_distance
            best_point = M

    return sum(best_point)

# Test cases
assert solve_gps_problem((0, 4, 5), (3, 0, 5), (3, 4, 0), (3, 4, 5)) == 8.64
assert solve_gps_problem((0, 0, 0), (1, 0, 0), (0, 1, 0), (1, 1, 0)) == 1.0

