from typing import Tuple
import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    prime_numbers = [i for i in range(1, total_tickets + 1) if is_prime(i)]
    non_primes = [i for i in range(1, total_tickets + 1) if not is_prime(i)]

    def combinations_count(lst: list, k: int) -> int:
        return math.comb(len(lst), k)

    # Calculate the number of valid combinations
    valid_combinations = 0

    # Case 1: Exactly 2 primes and 2 non-primes
    for p in range(2):
        prime_combinations = combinations_count(prime_numbers, 2 + p)
        non_prime_combinations = combinations_count(non_primes, chosen_tickets - (2 + p))
        valid_combinations += prime_combinations * non_prime_combinations

    # Case 2: Exactly 4 primes
    if len(prime_numbers) >= 4:
        valid_combinations += combinations_count(prime_numbers, 4)

    total_combinations = math.comb(total_tickets, chosen_tickets)

    probability = (valid_combinations / total_combinations) * 100

    # Ensure the sum is even
    if not is_prime(sum(prime_numbers[:2]) + sum(non_primes[:2])):
        valid_combinations -= combinations_count(prime_numbers, 3) * combinations_count(non_primes, 1)

    probability = (valid_combinations / total_combinations) * 100

    return round(probability, 1)

