def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> int:
    """
    Finds the minimum first-month payment 'm' to pay off a certain percentage of a debt within a given number of months,
    where each subsequent month's payment is a fixed ratio of the previous month.

    :param debt: Total debt amount
    :param target_percentage: Target percentage of debt to be paid off (as a decimal)
    :param months: Number of months to pay off the debt
    :param decay_ratio: Ratio by which each subsequent month's payment decreases compared to the previous one
    :return: Minimum first-month payment as an integer
    """

    def calculate_payment(month: int, m: float) -> float:
        return m * (decay_ratio ** (months - month))

    low, high = 0, debt / target_percentage
    while low < high:
        mid = (low + high) // 2
        remaining_debt = debt
        for month in range(1, months + 1):
            payment_this_month = calculate_payment(month, mid)
            remaining_debt -= payment_this_month
            if remaining_debt <= 0:
                break

        if remaining_debt > -target_percentage * debt:
            low = mid + 0.01
        else:
            high = mid

    return round(low)

