def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> Union[int, None]:
    if debt <= 0 or target_percentage < 0 or target_percentage > 1 or months <= 0 or decay_ratio <= 0:
        return None

    def calculate_remaining_debt(first_payment: float) -> float:
        remaining = debt * (1 - target_percentage)
        current_payment = first_payment
        for _ in range(months):
            remaining -= current_payment
            current_payment *= decay_ratio
        return remaining

    low, high = 0, int(debt / target_percentage)
    while low < high:
        mid = (low + high) // 2
        if calculate_remaining_debt(mid) > 1e-6:
            low = mid + 1
        else:
            high = mid

    return low

